import os
import re

import pytest

PROJECT = "/project"

SKIP_DIRS = {
    ".git", "node_modules", ".venv", "venv", "__pycache__", "dist", "build",
    ".tox", ".mypy_cache", ".pytest_cache", "target", "vendor", "tests", "test",
}
CODE_EXT = {".py", ".sh", ".bash", ".js", ".ts", ".mjs", ".cjs", ".go", ".rs",
            ".rb", ".yml", ".yaml", ".toml", ".ps1", ".mk", ".cfg"}
DOC_EXT = {".md", ".rst", ".txt"}
MAX_SIZE = 1_000_000

CHERRY = re.compile(r"cherry[-_ ]?pick", re.I)
MERGE = re.compile(r"\bmerge\b|\bmerge_|--no-ff|git\s+merge", re.I)
NEGATION = re.compile(
    r"\b(no|not|never|don't|dont|doesn't|without|instead of|rather than|forbid\w*|"
    r"prohibit\w*|must not|shall not|avoid\w*)\b",
    re.I,
)
COMMENT = re.compile(r"^\s*(#|//|\*|/\*|<!--|--)")


def _files(exts):
    for root, dirs, names in os.walk(PROJECT):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        for n in names:
            if n.startswith("test_") or n.endswith("_test.py"):
                continue
            if os.path.splitext(n)[1].lower() in exts:
                p = os.path.join(root, n)
                try:
                    if os.path.getsize(p) > MAX_SIZE:
                        continue
                    with open(p, encoding="utf-8", errors="ignore") as f:
                        yield p, f.read()
                except OSError:
                    continue


def _hotfix_files(exts):
    return [(p, t) for p, t in _files(exts) if re.search(r"hotfix", t, re.I)]


def test_hotfix_propagates_by_merge_not_cherry_pick():
    if not os.path.isdir(PROJECT):
        pytest.skip("project checkout not present")

    code = _hotfix_files(CODE_EXT)
    docs = _hotfix_files(DOC_EXT)
    if not code and not docs:
        pytest.skip("no hotfix workflow present in project")

    # Forbidden: cherry-pick used in hotfix-related code (non-comment, non-negated lines).
    offenders = []
    for p, t in code:
        for i, line in enumerate(t.splitlines(), 1):
            if CHERRY.search(line) and not COMMENT.match(line) and not NEGATION.search(line):
                offenders.append(f"{p}:{i}: {line.strip()}")
    assert not offenders, (
        "hotfix propagation must not use cherry-pick:\n" + "\n".join(offenders[:20])
    )

    # Docs must not instruct cherry-picking hotfixes (unless negated).
    doc_offenders = []
    for p, t in docs:
        for i, line in enumerate(t.splitlines(), 1):
            if CHERRY.search(line) and not NEGATION.search(line):
                doc_offenders.append(f"{p}:{i}: {line.strip()}")
    assert not doc_offenders, (
        "documentation prescribes cherry-pick for hotfixes:\n"
        + "\n".join(doc_offenders[:20])
    )

    # Required: merge evidence in hotfix-related material (prefer code).
    def has_merge(entries):
        for _, t in entries:
            for line in t.splitlines():
                if MERGE.search(line) and not (COMMENT.match(line) and not re.search(r"hotfix", line, re.I)):
                    return True
        return False

    assert has_merge(code) or (not code and has_merge(docs)), (
        "no evidence that hotfixes are propagated to the integration branch by merge"
    )
